func newRuleVersion() unsafe.Pointer { return unsafe.Pointer(new(documentparsingrule.RuleVersion)) }

func newNRuleVersion(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]documentparsingrule.RuleVersion, n)))
}

func ptrRuleVersion(p unsafe.Pointer, c int32) any {
	r := (*documentparsingrule.RuleVersion)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.RuleSetID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 4:
		return (*int64)(unsafe.Pointer(&r.VersionNumber))
	case 5:
		return (*string)(unsafe.Pointer(&r.Status))
	case 6:
		return &r.Label
	case 7:
		return (*string)(unsafe.Pointer(&r.ParserMode))
	case 8:
		return &r.MatchConfig
	case 9:
		return &r.RuleDocument
	case 10:
		return &r.ValidationSummary
	case 11:
		return &r.PublishedAt
	case 12:
		return (**string)(unsafe.Pointer(&r.PublishedByID))
	case 13:
		return &r.Version
	case 14:
		return &r.CreatedAt
	case 15:
		return &r.UpdatedAt
	}
	return nil
}

func valueRuleVersion(p unsafe.Pointer, c int32) any {
	r := (*documentparsingrule.RuleVersion)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.RuleSetID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.BusinessUnitID)
	case 4:
		return int64(r.VersionNumber)
	case 5:
		return string(r.Status)
	case 6:
		if r.Label == "" {
			return nil
		}
		return r.Label
	case 7:
		return string(r.ParserMode)
	case 8:
		return r.MatchConfig
	case 9:
		return r.RuleDocument
	case 10:
		if r.ValidationSummary == nil {
			return keel.EmptyJSONObject
		}
		return r.ValidationSummary
	case 11:
		if r.PublishedAt == nil {
			return nil
		}
		return *r.PublishedAt
	case 12:
		if r.PublishedByID == nil {
			return nil
		}
		return string(*r.PublishedByID)
	case 13:
		return r.Version
	case 14:
		return r.CreatedAt
	case 15:
		return r.UpdatedAt
	}
	return nil
}

func attachRuleVersion(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*documentparsingrule.RuleVersion)(p)
	switch rel {
	case 0:
		r.RuleSet = (*documentparsingrule.RuleSet)(child)
	}
}

func beforeCreateRuleVersion(ctx context.Context, p unsafe.Pointer) error {
	return (*documentparsingrule.RuleVersion)(p).BeforeCreate(ctx)
}

